WHERE del_status = 0
AND shop_id = #{shopId}
AND customer_id = #{customerId}
AND order_status = #{orderStatus}
AND order_no = #{orderNo}
AND shop_name LIKE CONCAT('%', #{shopName}, '%')
ORDER BY create_time DESC

