mapper.update:
UPDATE shop_order
SET order_status = #{newStatus}, update_time = #{updateTime}, version = version + 1
WHERE id = #{id}
AND order_status = #{oldStatus}
AND version = #{version}

UPDATE shop_order
SET order_status = 31, receive_time = #{receiveTime}, finish_time = #{finishTime},
	version = version + 1
WHERE id = #{id}
AND order_status = #{oldStatus}
AND version = #{version}

UPDATE shop_order
SET pay_status = 2, refund_amt = refund_amt + #{refundAmt}, version = version + 1
WHERE id = #{id} AND order_status < 30 AND version = #{version}

UPDATE shop_order
SET after_sale_status = #{afterSaleStatus}, version = version + 1
WHERE id = #{id} AND version = #{version}
